:root {
  --bg: #1b1b2f;
  --card: #2d2d44;
  --ink: #f5f5f5;
  --accent: #ffcc00;
  --muted: #9a9ab0;
  --danger: #ff5c5c;
  --border: #4a4a6a;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  color: var(--ink);
  background:
    repeating-linear-gradient(0deg, transparent 0 15px, rgba(255,255,255,.03) 15px 16px),
    repeating-linear-gradient(90deg, transparent 0 15px, rgba(255,255,255,.03) 15px 16px),
    var(--bg);
}

.card {
  width: 100%;
  max-width: 480px;
  padding: 28px 24px;
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 #000;
}

h1 {
  margin: 0 0 12px;
  font-size: 24px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 #000;
}

.counts {
  margin: 0 0 20px;
  color: var(--muted);
  font-size: 16px;
}

.counts span { color: var(--accent); font-weight: 700; }

.add-row { display: flex; gap: 8px; margin-bottom: 20px; }

input[type="text"] {
  flex: 1;
  min-width: 0;
  padding: 10px 12px;
  font: inherit;
  color: var(--ink);
  background: var(--bg);
  border: 3px solid var(--border);
  outline: none;
}

input[type="text"]:focus-visible {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(255, 204, 0, .35);
}

button {
  font: inherit;
  font-weight: 700;
  cursor: pointer;
  color: #1b1b2f;
  background: var(--accent);
  border: 3px solid #000;
  box-shadow: 3px 3px 0 #000;
  padding: 10px 16px;
  transition: transform .05s, box-shadow .05s;
}

button:hover { background: #ffd94d; }
button:focus-visible { outline: 3px solid var(--ink); outline-offset: 2px; }
button:active { transform: translate(3px, 3px); box-shadow: 0 0 0 #000; }

.list { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }

.list li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: var(--bg);
  border: 3px solid var(--border);
}

.list li label { display: flex; align-items: center; gap: 10px; flex: 1; cursor: pointer; }

.list input[type="checkbox"] {
  width: 20px; height: 20px; accent-color: var(--accent); flex: none; cursor: pointer;
}

.list input[type="checkbox"]:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }

.task-text { word-break: break-word; }

done .task-text, .list li.done .task-text {
  color: var(--muted);
  text-decoration: line-through;
}

.delete {
  background: var(--danger);
  color: #fff;
  padding: 6px 10px;
  box-shadow: 2px 2px 0 #000;
}

.delete:hover { background: #ff7b7b; }

.empty { color: var(--muted); font-size: 16px; margin: 16px 0 0; }
.empty[hidden] { display: none; }

.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

@media (max-width: 400px) {
  .card { padding: 20px 16px; box-shadow: 5px 5px 0 #000; }
  h1 { font-size: 20px; }
}

(function () {
  'use strict';

  var tasks = [];
  var nextId = 1;

  var form = document.getElementById('todo-form');
  var input = document.getElementById('todo-input');
  var list = document.getElementById('todo-list');
  var totalEl = document.getElementById('todo-total');
  var remainingEl = document.getElementById('remaining');
  var emptyMsg = document.getElementById('empty-msg');

  function updateCounts() {
    var remaining = tasks.filter(function (t) { return !t.completed; }).length;
    totalEl.textContent = String(tasks.length);
    remainingEl.textContent = String(remaining);
    emptyMsg.hidden = tasks.length > 0;
  }

  function createTaskElement(task) {
    var li = document.createElement('li');
    li.dataset.id = String(task.id);
    if (task.completed) li.classList.add('done');

    var label = document.createElement('label');
    label.htmlFor = 'todo-check-' + task.id;

    var checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.id = 'todo-check-' + task.id;
    checkbox.checked = task.completed;
    checkbox.setAttribute('aria-label', 'Mark task complete: ' + task.text);
    checkbox.addEventListener('change', function () {
      task.completed = checkbox.checked;
      li.classList.toggle('done', task.completed);
      updateCounts();
    });

    var text = document.createElement('span');
    text.id = 'todo-text-' + task.id;
    text.className = 'task-text';
    text.textContent = task.text;

    label.appendChild(checkbox);
    label.appendChild(text);

    var del = document.createElement('button');
    del.type = 'button';
    del.id = 'todo-delete-' + task.id;
    del.className = 'delete';
    del.textContent = 'Delete';
    del.setAttribute('aria-label', 'Delete task: ' + task.text);
    del.addEventListener('click', function () {
      tasks = tasks.filter(function (t) { return t.id !== task.id; });
      li.remove();
      updateCounts();
    });

    li.appendChild(label);
    li.appendChild(del);
    return li;
  }

  function addTask() {
    var value = input.value.trim();
    if (!value) { input.value = ''; return; }
    var task = { id: nextId++, text: value, completed: false };
    tasks.push(task);
    list.appendChild(createTaskElement(task));
    input.value = '';
    input.focus();
    updateCounts();
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    addTask();
  });

  updateCounts();
})();
